exports.push([module.i, "@charset \"UTF-8\";\r\n/**\r\n * 这里是uni-app内置的常用样式变量\r\n *\r\n * uni-app 官方扩展插件及插件市场（https://ext.dcloud.net.cn）上很多三方插件均使用了这些样式变量\r\n * 如果你是插件开发者，建议你使用scss预处理，并在插件代码中直接使用这些变量（无需 import 这个文件），方便用户通过搭积木的方式开发整体风格一致的App\r\n *\r\n */\r\n/**\r\n * 如果你是App开发者（插件使用者），你可以通过修改这些变量来定制自己的插件主题，实现自定义主题功能\r\n *\r\n * 如果你的项目同样使用了scss预处理，你也可以直接在你的 scss 代码中使用如下变量，同时无需 import 这个文件\r\n */\r\n/* 颜色变量 */\r\n/* 行为相关颜色 */\r\n/* 文字基本颜色 */\r\n/* 背景颜色 */\r\n/* 边框颜色 */\r\n/* 尺寸变量 */\r\n/* 文字尺寸 */\r\n/* 图片尺寸 */\r\n/* Border Radius */\r\n/* 水平间距 */\r\n/* 垂直间距 */\r\n/* 透明度 */\r\n/* 文章场景相关 */\r\n/* 全局容器样式：保留原有适配，微调统一 */\n.match-list[data-v-da4482ba] {\r\n  background-color: #f5f5f5;\r\n  box-sizing: border-box;\r\n  padding-bottom: 140rpx;\n}\r\n/* 抽屉样式：保留原有逻辑，微调统一 */\n.drawer-wrapper[data-v-da4482ba] {\r\n  width: 100%;\r\n  margin-bottom: 4rpx;\n}\n.sticky-header[data-v-da4482ba] {\r\n  position: -webkit-sticky;\r\n  position: sticky;\r\n  z-index: 9;\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n  padding: 18rpx 20rpx 12rpx 20rpx;\r\n  background-color: #f5f5f5;\r\n  border-bottom: 1rpx solid #eee;\r\n  font-size: 26rpx;\r\n  color: #333;\n}\n.sticky-header .arrow-icon[data-v-da4482ba] {\r\n  transition: -webkit-transform 0.2s;\r\n  transition: transform 0.2s;\r\n  transition: transform 0.2s, -webkit-transform 0.2s;\n}\n.sticky-header .rotated[data-v-da4482ba] {\r\n  -webkit-transform: rotate(180deg);\r\n          transform: rotate(180deg);\n}\n.drawer-content[data-v-da4482ba] {\r\n  width: 100%;\r\n  transition: all 0.2s ease;\n}\r\n/* ========== 核心重构：比赛行样式（和其他组件完全统一） ========== */\n.match-row[data-v-da4482ba] {\r\n  background-color: #fff;\r\n  border-bottom: 1rpx solid #DEDEDE;\r\n  padding: 0rpx 20rpx;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 0;\r\n  margin-bottom: 4rpx;\r\n  border-radius: 8rpx;\r\n  box-shadow: 0 2rpx 5rpx rgba(0, 0, 0, 0.05);\n}\r\n/* 状态行：和其他组件完全一致 */\n.match-status-row[data-v-da4482ba] {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n  width: 100%;\r\n  border-bottom: 1rpx solid #f5f5f5;\n}\n.match-status-row .status-left[data-v-da4482ba] {\r\n  width: 200rpx;\r\n  display: flex;\r\n  align-items: center;\n}\n.match-status-row .single-tag[data-v-da4482ba] {\r\n  display: inline-block;\r\n  padding-left: 6rpx;\r\n  width: 60rpx;\r\n  background: #b71c1c;\r\n  color: #fff;\r\n  text-align: left;\r\n  font-size: 22rpx;\r\n  border-top-right-radius: 15rpx;\r\n  border-bottom-right-radius: 16rpx;\r\n  margin-right: 10rpx;\n}\n.match-status-row .status-right .ai-analysis-btn[data-v-da4482ba] {\r\n  font-size: 24rpx;\r\n  color: #06f;\r\n  cursor: pointer;\r\n  transition: opacity 0.2s;\r\n  letter-spacing: 4rpx;\n}\n.match-status-row .status-right .ai-analysis-btn[data-v-da4482ba]:active {\r\n  opacity: 0.8;\n}\r\n/* 核心：整体左右布局（和其他组件完全一致） */\n.main-content-row[data-v-da4482ba] {\r\n  display: flex;\r\n  width: 100%;\r\n  gap: 16rpx;\r\n  padding: 8rpx 0;\n}\r\n/* 左侧区域：固定宽度，垂直排列 */\n.main-left[data-v-da4482ba] {\r\n  width: 160rpx;\r\n  display: flex;\r\n  flex-direction: column;\r\n  flex-shrink: 0;\r\n  gap: 8rpx;\n}\r\n/* 右侧区域：自适应宽度，垂直排列 */\n.main-right[data-v-da4482ba] {\r\n  flex: 1;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 8rpx;\r\n  background: #fff;\n}\r\n/* 左侧子元素：样式统一 */\n.top-left[data-v-da4482ba] {\r\n  margin-top: 8rpx;\r\n  display: flex;\r\n  justify-content: center;\r\n  align-items: center;\n}\n.league-name-row[data-v-da4482ba] {\r\n  display: flex;\r\n  align-items: center;\r\n  width: 100%;\n}\n.league-name[data-v-da4482ba] {\r\n  font-size: 22rpx;\r\n  color: #777;\n}\n.bottom-left[data-v-da4482ba] {\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: flex-start;\r\n  text-align: left;\r\n  gap: 2rpx;\n}\n.serial-number[data-v-da4482ba], .match-time[data-v-da4482ba] {\r\n  width: 100%;\r\n  font-size: 20rpx;\r\n  color: #999;\r\n  text-align: center;\n}\r\n/* 右侧子元素：样式统一 */\n.top-right[data-v-da4482ba] {\r\n  flex: 1;\r\n  text-align: center;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 6rpx;\n}\r\n/* 队名VS：样式统一 */\n.team-vs[data-v-da4482ba] {\r\n  font-size: 24rpx;\r\n  color: #333;\r\n  text-align: center;\r\n  padding: 4rpx 0;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  width: 100%;\n}\n.team-vs .team-name[data-v-da4482ba] {\r\n  flex: 1;\r\n  text-align: center;\r\n  white-space: nowrap;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\n}\n.team-vs .team-name.away[data-v-da4482ba] {\r\n  text-align: right;\r\n  padding-right: 10rpx;\n}\n.team-vs .team-name.home[data-v-da4482ba] {\r\n  text-align: left;\r\n  padding-left: 10rpx;\n}\n.team-vs .vs-text[data-v-da4482ba] {\r\n  width: 40rpx;\r\n  text-align: center;\r\n  flex-shrink: 0;\r\n  font-weight: 500;\n}\r\n/* 胜率行：样式统一 */\n.rate-row[data-v-da4482ba] {\r\n  width: 100%;\r\n  display: flex;\r\n  align-items: center;\r\n  font-size: 22rpx;\r\n  color: #999;\r\n  justify-content: center;\r\n  gap: 10rpx;\n}\n.rate-row .rate-text[data-v-da4482ba] {\r\n  flex: 1;\r\n  text-align: center;\r\n  white-space: nowrap;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\n}\n.rate-row .rate-text.away[data-v-da4482ba] {\r\n  text-align: right;\r\n  padding-right: 10rpx;\n}\n.rate-row .rate-text.home[data-v-da4482ba] {\r\n  text-align: left;\r\n  padding-left: 10rpx;\n}\r\n/* 大小分选项区：样式统一，保留三列结构 */\n.bottom-right[data-v-da4482ba] {\r\n  width: 100%;\n}\n.odds-trigger-area[data-v-da4482ba] {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  border: 1rpx solid #DEDEDE;\r\n  border-radius: 8rpx;\r\n  padding: 8rpx 0;\r\n  background-color: #f9f9f9;\r\n  cursor: pointer;\r\n  width: 100%;\r\n  box-sizing: border-box;\r\n  transition: all 0.2s ease;\n}\r\n/* 赔率按钮行：保留三列结构，样式统一 */\n.odds-row[data-v-da4482ba] {\r\n  width: 100%;\r\n  display: flex;\r\n  gap: 2rpx;\r\n  margin-top: 0;\n}\r\n/* 按钮样式：统一交互效果，保留三列逻辑 */\n.match-cell[data-v-da4482ba] {\r\n  flex: 1;\r\n  text-align: center;\r\n  padding: 12rpx 0;\r\n  background-color: #f0f0f0;\r\n  color: #666;\r\n  font-size: 24rpx;\r\n  cursor: pointer;\r\n  /* 中间分值按钮：特殊样式保留 */\n}\n.match-cell.selected[data-v-da4482ba] {\r\n  background-color: #d92929;\r\n  color: #fff;\n}\n.match-cell[data-v-da4482ba]:active {\r\n  background: #e5e5e5;\n}\n.match-cell.selected[data-v-da4482ba]:active {\r\n  background: #c62828;\n}\n.match-cell.middle[data-v-da4482ba] {\r\n  color: #999;\r\n  pointer-events: none;\r\n  /* 禁止点击 */\n}\r\n/* 全局样式：隐藏滚动条 */\n[data-v-da4482ba]::-webkit-scrollbar {\r\n  display: none;\n}\r\n", ""]);
